"""Stage 16T document authoring and static verification only; no random streams."""
import json, hashlib, math
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'ml_v4/design/challenge'
VERSION='v4.challenge.protocol.1'
def load(p): return json.loads((ROOT/p).read_text(encoding='utf-8'))
def sha(p): return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def write(name,obj):
    with (OUT/name).open('x',encoding='utf-8',newline='\n') as f: json.dump({'protocol_version':VERSION,**obj},f,indent=2,sort_keys=True,allow_nan=False);f.write('\n')

