expected['ml_v4/evidence/stage16s/preservation_verification.json']=sha('ml_v4/evidence/stage16s/preservation_verification.json')
before={p:sha(p) for p in expected}; assert before==expected
if OUT.exists(): raise FileExistsError('Existing challenge design; refuse overwrite')
